head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil11020";
scwin.directInsertView = null;
scwin.setOpener = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_formKorNm", fn: function () { return String((dma_pageContext.get("formKorNm") ?? "")); } },
        { childId: "cal_searchBeginDd", fn: function () { return String(String((dma_pageContext.get("searchBeginDd") ?? ""))); } },
        { childId: "cal_searchEndDd", fn: function () { return String(String((dma_pageContext.get("searchEndDd") ?? ""))); } },
        { childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("endListPage")) + " 페이지)"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.directInsertView = $c.util.getComponent('directInsertView');
        scwin.setOpener = setOpener;
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil11020.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cal_searchBeginDd_onblur
 * @description cal_searchBeginDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_searchBeginDd_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_searchBeginDd"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11020.cal_searchBeginDd_onblur' }); }
};

/**
 * @method
 * @name cal_searchEndDd_onblur
 * @description cal_searchEndDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_searchEndDd_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_searchEndDd"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11020.cal_searchEndDd_onblur' }); }
};

/**
 * @method
 * @name btn_searchList_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11020.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name grd_list_oncellclick
 * @description grd_list 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_list_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_list');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_list */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_setOpener (인자 미해석) */
        if (columnId === "applNo") { /* TODO Stage2: [sdd] 미실현 행 동작: fn_setOpener (as-is 인자를 못 옮겼습니다) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — fn_setOpener'); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_list.oncellclick' });
    }
};

/**
 * @method
 * @name input_98_onclick
 * @description input_98 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_98_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.fnDirectCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil11020.input_98_onclick' }); }
};

/**
 * @method
 * @name btn_setDitectOpener_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_setDitectOpener_onclick = async function(e){
    try {
        await scwin.setDitectOpener()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11020.btn_setDitectOpener_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_searchListReq",
        target: "dlt_list=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_90").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_list_fmt_formKorNm
 * @description grd list fmt form Kor Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_list_fmt_formKorNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_list");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "langTpCd") ?? '') : '');
        if (v === '0') { return String((dl && dl.getCellData ? dl.getCellData(r, "formKorNm") : '') ?? ''); }
        return (console.error('[sdd] 미실현 라벨 갈래: formKorNm (expression)'), String(data ?? ''));
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_list.formKorNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_list_fmt_column5
 * @description grd list fmt column5 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_list_fmt_column5 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_list");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "disclsAcptTpCd") ?? '') : '');
        if (v === 'F') { return "최초문서"; }
        if (v === 'M') { return "본문정정"; }
        if (v === 'U') { return "첨부정정"; }
        if (v === 'A') { return "첨부추가"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_list.column5" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_list_fmt_column6
 * @description grd list fmt column6 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_list_fmt_column6 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_list");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "langTpCd") ?? '') : '');
        if (v === '0') { return "국문"; }
        if (v === '1') { return "영문"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_list.column6" }); return String(data ?? ''); }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    await scwin.tx_fn_searchList();
};

function setOpener(form_cd, form_ver, num) {
    const fullFormNm = scwin.ignoreSpaces($('#fullFormNm' + num).text());
    $('#formCd', parent.opener.document).val(form_cd);
    $('#formVer', parent.opener.document).val(form_ver);
    $('#formKorNm', parent.opener.document).val(fullFormNm);
    $c.win.closePopup();
}

/**
 * @method
 * @name setDitectOpener
 * @description set Ditect Opener 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setDitectOpener = async function () {
    if (($c.util.getComponent('ipt_directInsert').getValue() == null ? '' : String($c.util.getComponent('ipt_directInsert').getValue())) === '' || $c.util.getComponent('ipt_directInsert').getValue() == null) {
        await $c.win.alert("공시서식명을 입력하세요.");
        $c.util.getComponent("ipt_directInsert").focus();
        return;
    }
    if (scwin.calBytes($c.util.getComponent('ipt_directInsert').getValue()) > 800) {
        await $c.win.alert("상담내용은 한글 400자 이하, 숫자/영문 800자 이하까지만 입력이 가능합니다.");
        $c.util.getComponent("ipt_directInsert").focus();
        return;
    }
    $('#formCd', parent.opener.document).val('');
    $('#formVer', parent.opener.document).val('');
    $('#formKorNm', parent.opener.document).val($c.util.getComponent('ipt_directInsert').getValue());
    $c.win.closePopup();
};

/**
 * @method
 * @name calBytes
 * @description cal Bytes 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.calBytes = function (str) {
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};

/**
 * @method
 * @name fnDirectCheck
 * @description fn Direct Check 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.fnDirectCheck = function (obj) {
    if (obj.checked) {
        scwin.directInsertView.setStyle("display", "");
    } else {
        scwin.directInsertView.setStyle("display", "none");
    }
};

/**
 * @method
 * @name ignoreSpaces
 * @description ignore Spaces 처리
 * @param {*} _str _str
 * @returns {void}
 * @hidden N
 */
scwin.ignoreSpaces = function (_str) {

    return _str.replace(/\s/g, "");
};

/**
 * @method
 * @name krxpage_pagenavigator_90_onclick
 * @description krxpage_pagenavigator_90 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_90_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_90.page' }); } await scwin.tx_fn_searchList(); };
